def apply(inputs, premises):
    total = int(inputs["ticket_price"])
    checked_position = 0
    n = len(inputs["dimension_totals"])
    for i in range(n):
        if not bool(inputs["is_free_carryon"][i]):
            schedule_index = min(checked_position, len(inputs["checked_base_fee_schedule"]) - 1)
            base_fee = int(inputs["checked_base_fee_schedule"][schedule_index])
            dimension_total = int(inputs["dimension_totals"][i])
            weight = int(inputs["weights"][i])
            size_fee = 0
            if dimension_total > 62 and dimension_total <= 65:
                size_fee = int(inputs["oversize_fee_schedule"][0])
            if dimension_total > 65:
                size_fee = int(inputs["oversize_fee_schedule"][1])
            weight_fee = 0
            if weight > 50 and weight <= 53:
                weight_fee = int(inputs["overweight_fee_schedule"][0])
            if weight > 53 and weight <= 70:
                weight_fee = int(inputs["overweight_fee_schedule"][1])
            if weight > 70:
                weight_fee = int(inputs["overweight_fee_schedule"][2])
            total = total + base_fee + max(size_fee, weight_fee)
            checked_position = checked_position + 1
    return {"answer": int(total)}

